 private function applySettlement(array $data,int $cost,string $paid,bool $reverse=true):array
 {
  $f=$data['f'];$selector=$data['selector'];$selector['cost_line_id']=$cost;$native=$this->container->get(\MyInvoice\Service\Property\Services\Settlement\SettlementOriginAdapter::class)->current($f['supplier'],$f['units']['U02'],$f['service']['id'],'2027-04-01',[$selector]);$origin=$native['origins'][0];
  $facts=['supplier_id'=>$f['supplier'],'unit_id'=>$f['units']['U02'],'service_id'=>$f['service']['id'],'segment_key'=>'SYNTHETIC-LIFECYCLE-2026','period_from'=>'2026-01-01','period_to'=>'2026-12-31','cutoff_at'=>'2026-12-31T23:59:59+01:00','known_at'=>'2027-04-01T12:00:00+02:00','recipient_ids'=>[$f['clients'][1]],'evidence'=>'Synthetic external final settlement and recipient legal title','prescribed_cents'=>$origin['prescribed_cents'],'paid_cents'=>$paid,'actual_cents'=>$data['actual_cents']??'1120000','origins'=>$native['origins'],'cutoff_allocations'=>[],'cost'=>array_values($native['costs'])[0]];
  $doc=\MyInvoice\Service\Property\Services\Settlement\SettlementDocument::fromEvidence($facts);$saved=$this->container->get(\MyInvoice\Repository\Property\Services\Settlement\SettlementDocumentRepository::class)->save($f['supplier'],$doc,[$selector],'2027-04-01',0,'lifecycle-document',$f['actor']);$request=['accounting_date'=>'2027-04-01','evidence'=>'Synthetic final lifecycle disposition','advances'=>[['origin_key'=>$origin['kind'].':'.$origin['id'],'applied_cents'=>$data['actual_cents']??'1120000']],'reliefs'=>[],'opening_credits'=>in_array($paid,['1200000','12000000'],true)?[['origin_key'=>$origin['kind'].':'.$origin['id'],'amount_cents'=>$data['credit_cents']??'80000','entitlement'=>['party_ids'=>[$f['clients'][1]],'evidence'=>'Synthetic original service recipient credit title','due_date'=>'2027-04-30','account_code'=>'379.910']]]:[],'new_claim'=>null];
  $owner=$this->container->get(\MyInvoice\Repository\Property\Services\Settlement\SettlementApplicationRepository::class);$preview=$owner->preview($f['supplier'],$saved['id'],$request,0);$done=$owner->apply($f['supplier'],$saved['id'],$request,0,$preview['preview_hash'],'lifecycle-apply',$f['actor']);self::assertGreaterThan(0,$done['id']);
  $reconcile=(new \MyInvoice\Service\Property\Receivables\PropertyReconciliation($this->db))->at($f['supplier'],'2027-04-01',$f['units']['U02']);self::assertTrue($reconcile['matches']);if($origin['debt_id']!==null){$history=(new \MyInvoice\Repository\Property\Receivables\FinancialHistoryRepository($this->db))->readForDebts($f['supplier'],[$origin['debt_id']]);$totals=\MyInvoice\Service\Property\Receivables\ReceivableTimeline::accountingDate($history['debts'][$origin['debt_id']]['events'],'2027-04-01',\MyInvoice\Repository\Property\Receivables\PartyEventRepository::now());self::assertSame($paid==='0'?'1120000':($data['claim_cents']??'120000'),$totals['gross_receivable_cents']);}self::assertSame(in_array($paid,['1200000','12000000'],true)?($data['credit_cents']??'80000'):'0',$reconcile['subledger_cents']['credit']);
  $q=$this->db->pdo()->prepare("SELECT SUM(CASE l.side WHEN 'debit' THEN l.amount ELSE -l.amount END) balance FROM journal_entry_lines l JOIN journal_entries e ON e.id=l.entry_id AND e.supplier_id=l.supplier_id JOIN chart_of_accounts c ON c.id=l.account_id AND c.supplier_id=l.supplier_id WHERE l.supplier_id=? AND c.account_code='315.210' AND e.entry_date<='2027-04-01'");$q->execute([$f['supplier']]);self::assertSame('0.00',$q->fetchColumn());
  if($reverse){$owner->reverse($f['supplier'],$done['id'],'2027-04-02',1,'Synthetic lifecycle settlement correction','lifecycle-reverse',$f['actor']);self::assertFalse((new \MyInvoice\Service\Property\Services\Settlement\SettlementHistory($this->db))->application($f['supplier'],$done['id'],true)['active']);}return $done;
 }
