  $cat=(new \MyInvoice\Service\Accounting\Dimension\SystemDimensionCatalog($this->db))->ensureForFramework($supplier,'2027-04-01');$kind=$this->container->get(\MyInvoice\Service\Accounting\Dimension\DimensionService::class)->createValue($supplier,$cat['activity_kind']['id'],['code'=>'SYNTHETIC-SERVICE','name'=>'Synthetic service activity'],$f['actor']);$policyDims[$cat['activity']['id']]=$cat['activity']['values']['main'];$policyDims[$cat['activity_kind']['id']]=(int)$kind['id'];$policyDims[$cat['tax_regime']['id']]=$cat['tax_regime']['values']['subject'];  $state=['profile'=>$policy,'allocation_ref'=>'Synthetic original service allocation','counterpart_ref'=>'Synthetic original supplier estimate','prescribed_cents'=>'12000000','paid_cents'=>$paid,'settled_cents'=>'0','cancelled_unpaid_cents'=>'0','unpaid_cases'=>$links,'recipient_ids'=>[$f['clients'][1]]];if($policy==='service_profit_and_loss'&&$withPolicy)$state['accrual_unwind']=['expense_account'=>'502','coverage_account'=>'649','expense_dimensions'=>$policyDims,'coverage_dimensions'=>$policyDims,'evidence_ref'=>'Synthetic signed original P&L accounting policy and journal reconciliation'];
