 private function openingLifecycle(string $policy,bool $fullyPaid):void
 {
  $d=$this->openingBase($policy,$fullyPaid);$f=$d['f'];$before=(new PaymentJournalProof($this->db))->current($f['supplier'],$d['batch']['journal_entry_id']);$invoice=$this->invoice($d);$d['owner']->unwind($f['supplier'],$d['case'],'2027-04-01',$f['actor']);self::assertSame($before,(new PaymentJournalProof($this->db))->current($f['supplier'],$d['batch']['journal_entry_id']));$done=$d['owner']->finalize($f['supplier'],$d['case'],$invoice['invoice'],$invoice['line']['id'],'2027-04-01','Synthetic proven final service allocation',$f['actor']);$this->applySettlement($d,$done['cost_line_id'],$d['paid']);
  if($policy==='service_profit_and_loss'){$q=$this->db->pdo()->prepare("SELECT c.account_code,SUM(CASE l.side WHEN 'debit' THEN l.amount ELSE -l.amount END) balance FROM journal_entry_lines l JOIN chart_of_accounts c ON c.id=l.account_id AND c.supplier_id=l.supplier_id WHERE l.supplier_id=? AND c.account_code IN ('502','649') GROUP BY c.account_code");$q->execute([$f['supplier']]);self::assertSame(['502'=>'2000.00','649'=>'-2000.00'],array_column($q->fetchAll(\PDO::FETCH_ASSOC),'balance','account_code'));}
 }
 private function lifecycle(string $policy):void
 {
  $d=$this->base($policy);$f=$d['f'];$invoice=$this->invoice($d);$owner=$d['owner'];
  try{$owner->finalize($f['supplier'],$d['case'],$invoice['invoice'],$invoice['line']['id'],'2027-04-01','Synthetic final allocation title',$f['actor']);self::fail('Ununwound estimate finalized');}catch(\DomainException $e){self::assertSame('settlement_lifecycle_estimate_not_unwound',$e->getMessage());}
  $unwound=$owner->unwind($f['supplier'],$d['case'],'2027-04-01',$f['actor']);self::assertCount(count($d['entries']),$unwound);foreach($d['entries'] as $i=>$entry)self::assertSame($unwound[$i],(new PaymentJournalProof($this->db))->current($f['supplier'],$entry)['entry']['reversed_by']);
  $done=$owner->finalize($f['supplier'],$d['case'],$invoice['invoice'],$invoice['line']['id'],'2027-04-01','Synthetic final allocation title',$f['actor']);self::assertSame('1120000',$done['amount_cents']);self::assertGreaterThan(0,$done['cost_line_id']);self::assertSame($done,$owner->current($f['supplier'],$d['case'])['final']);try{$owner->finalize($f['supplier'],$d['case'],$invoice['invoice'],$invoice['line']['id'],'2027-04-01','Synthetic duplicate final coverage',$f['actor']);self::fail('Duplicate final coverage created income');}catch(\DomainException $e){self::assertSame('settlement_lifecycle_event_exists',$e->getMessage());}try{$owner->openCase($f['supplier'],$f['units']['U02'],$f['service']['id'],'2026-01-01','2026-12-31',$policy==='service_balance_sheet'?'service_profit_and_loss':'service_balance_sheet','Synthetic forbidden policy mixing',$f['actor'],'315.210');self::fail('Policy mixed in one service period');}catch(\DomainException $e){self::assertSame('settlement_lifecycle_case_overlap',$e->getMessage());}
  $events=(new \ReflectionMethod($owner,'events'))->invoke($owner,$f['supplier'],$d['case']);$unwind=$events['unwind-0'];$bad=$unwind['receipt'];$bad['ledger']['lines'][0]['amount']='1.00';$this->db->pdo()->exec('SAVEPOINT forged_lifecycle_receipt');$this->db->pdo()->prepare('UPDATE property_service_lifecycle_events SET receipt_json=?,receipt_hash=? WHERE supplier_id=? AND id=?')->execute([json_encode($bad,JSON_THROW_ON_ERROR),\MyInvoice\Service\Property\PropertyInput::hash($bad),$f['supplier'],$unwind['id']]);try{$owner->current($f['supplier'],$d['case']);self::fail('Forged native unwind receipt accepted');}catch(\DomainException $e){self::assertSame('settlement_lifecycle_unwind_proof',$e->getMessage());}finally{$this->db->pdo()->exec('ROLLBACK TO SAVEPOINT forged_lifecycle_receipt');}
  try{$this->container->get(PostingService::class)->reverse($f['supplier'],$invoice['entry'],['entry_date'=>'2027-04-02','posted_by'=>$f['actor']]);self::fail('Generic mutation of bound final invoice accepted');}catch(\MyInvoice\Service\Accounting\PostingException $e){self::assertSame('property_payment_source_immutable',$e->errorCode);}
try{(new \MyInvoice\Service\Property\Services\Settlement\SettlementUseGuard($this->db))->assertEntriesMutable($f['supplier'],[$invoice['entry']]);self::fail('Lifecycle source guard accepted bound invoice');}catch(\MyInvoice\Service\Property\Charges\Issuance\IssuanceException $e){self::assertSame('property_service_settlement_owner_required',$e->errorCode);}$this->applySettlement($d,$done['cost_line_id'],'0');
  $q=$this->db->pdo()->prepare("SELECT c.account_code,SUM(CASE l.side WHEN 'debit' THEN l.amount ELSE -l.amount END) balance FROM journal_entries e JOIN journal_entry_lines l ON l.entry_id=e.id AND l.supplier_id=e.supplier_id JOIN chart_of_accounts c ON c.id=l.account_id AND c.supplier_id=l.supplier_id WHERE e.supplier_id=? AND e.entry_date BETWEEN '2027-01-01' AND '2027-12-31' AND c.account_code IN ('502','649') GROUP BY c.account_code");$q->execute([$f['supplier']]);$sums=array_column($q->fetchAll(\PDO::FETCH_ASSOC),'balance','account_code');if($policy==='service_profit_and_loss'){self::assertSame('200.00',$sums['502']);self::assertSame('-200.00',$sums['649']);}else self::assertSame([],$sums);
 }
